create or replace function public.admin_courier_action_v308(p_admin_session_token text,p_courier_id text,p_action text) returns jsonb language plpgsql security definer set search_path=public,private,extensions,pg_temp as $$ declare v_admin_id text; v_action text:=lower(trim(coalesce(p_action,''))); v_linked boolean; begin v_admin_id:=private.require_admin_session_v147(p_admin_session_token); if coalesce(v_admin_id,'')='' then return jsonb_build_object('ok',false,'error','INVALID_ADMIN_SESSION'); end if; if v_action='toggle' then update public.couriers set is_active=not coalesce(is_active,true) where id::text=p_courier_id; if not found then return jsonb_build_object('ok',false,'error','COURIER_NOT_FOUND'); end if; return jsonb_build_object('ok',true,'result','TOGGLED'); elsif v_action='delete' then select exists(select 1 from public.orders where courier_id::text=p_courier_id limit 1) into v_linked; if v_linked then update public.couriers set is_active=false where id::text=p_courier_id; else delete from public.couriers where id::text=p_courier_id; end if; if not found then return jsonb_build_object('ok',false,'error','COURIER_NOT_FOUND'); end if; return jsonb_build_object('ok',true,'result',case when v_linked then 'DISABLED_LINKED' else 'DELETED' end); end if; return jsonb_build_object('ok',false,'error','UNSUPPORTED_ACTION'); end; $$;
revoke all on function public.admin_courier_action_v308 from public;
grant execute on function public.admin_courier_action_v308 to anon, authenticated;

create or replace function public.branch_courier_action_v308(p_branch_session_token text,p_courier_id text,p_action text) returns jsonb language plpgsql security definer set search_path=public,private,extensions,pg_temp as $$ declare v_branch_id text; v_action text:=lower(trim(coalesce(p_action,''))); v_linked boolean; begin v_branch_id:=private.require_branch_session_v148(p_branch_session_token); if coalesce(v_branch_id,'')='' then return jsonb_build_object('ok',false,'error','INVALID_BRANCH_SESSION'); end if; if not exists(select 1 from public.couriers where id::text=p_courier_id and branch_id::text=v_branch_id) then return jsonb_build_object('ok',false,'error','COURIER_NOT_FOUND_OR_NOT_OWNED'); end if; if v_action='toggle' then update public.couriers set is_active=not coalesce(is_active,true) where id::text=p_courier_id and branch_id::text=v_branch_id; return jsonb_build_object('ok',true,'result','TOGGLED'); elsif v_action='delete' then select exists(select 1 from public.orders where courier_id::text=p_courier_id limit 1) into v_linked; if v_linked then update public.couriers set is_active=false where id::text=p_courier_id and branch_id::text=v_branch_id; else delete from public.couriers where id::text=p_courier_id and branch_id::text=v_branch_id; end if; return jsonb_build_object('ok',true,'result',case when v_linked then 'DISABLED_LINKED' else 'DELETED' end); end if; return jsonb_build_object('ok',false,'error','UNSUPPORTED_ACTION'); end; $$;
revoke all on function public.branch_courier_action_v308 from public;
grant execute on function public.branch_courier_action_v308 to anon, authenticated;